    const noMigrationsPending = iconsBefore === 0 && colorsBefore === 0;
    const descriptionText = strings.settings.items.frontmatterMigration.desc.replace("{icons}", iconsBefore.toString()).replace("{colors}", colorsBefore.toString());
    descriptionEl.createDiv({ text: descriptionText });
    const shouldShow = !noMigrationsPending && plugin.settings.saveMetadataToFrontmatter;
    migrateButton == null ? void 0 : migrateButton.setDisabled(!plugin.settings.saveMetadataToFrontmatter || noMigrationsPending);
    migrationSetting.settingEl.toggle(shouldShow);
